def solve(strs):
    strs = [max(s, s[::-1]) for s in strs]
    ans = ""
    for i, s in enumerate(strs):
        for candidate in [s, s[::-1]]:
            for j in range(len(candidate)):
                curr = candidate[j:] + "".join(strs[i+1:]) + "".join(strs[:i]) + candidate[:j]
                if curr > ans: ans = curr
    return ans

